new file mode 100644
+type routeCache struct {
+	entries map[string]cachedResp
+	ttl     time.Duration
+}
+
+func (c *routeCache) get(key string) (cachedResp, bool) {
+	e, ok := c.entries[key]
+	if !ok || time.Since(e.at) > c.ttl { return cachedResp{}, false }
+	return e, true
+}
+
+func (c *routeCache) put(key string, r cachedResp) { c.entries[key] = r }
